// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";



/* ------------------------------------------------------------------ */
/* Types                                                               */
/* ------------------------------------------------------------------ */

export type SubmitState = "idle" | "loading" | "success";

export interface MultiStateSubmitButtonProps {
  /** Current visual state. The parent owns it, so the button works with any async flow. */
  state?: SubmitState;
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  type?: "button" | "submit" | "reset";
  disabled?: boolean;
  /** Label shown in the idle state. */
  children?: React.ReactNode;
  loadingText?: string;
  successText?: string;
  className?: string;
}



/* ------------------------------------------------------------------ */
/* Spinner: a faint track with a rotating arc                          */
/* ------------------------------------------------------------------ */

function Spinner() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className="size-[18px] animate-spin" aria-hidden="true">
      <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2.5" className="opacity-25" />
      <path d="M21 12a9 9 0 0 0-9-9" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
    </svg>
  );
}



/* ------------------------------------------------------------------ */
/* Checkmark that draws itself (circle first, then the tick)           */
/* ------------------------------------------------------------------ */

function AnimatedCheck({ reduced }: { reduced: boolean }) {
  const t = (duration: number, delay = 0) => ({ duration: reduced ? 0 : duration, delay: reduced ? 0 : delay, ease: "easeOut" as const });
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="size-5" aria-hidden="true">
      <motion.circle cx="12" cy="12" r="9" initial={{ pathLength: 0, opacity: 0 }} animate={{ pathLength: 1, opacity: 0.4 }} transition={t(0.45)} />
      <motion.path d="M7.5 12.5l3 3 6-6.5" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={t(0.4, 0.3)} />
    </svg>
  );
}



/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

export const MultiStateSubmitButton = React.forwardRef<HTMLButtonElement, MultiStateSubmitButtonProps>(
  (
    {
      state = "idle",
      onClick,
      type = "button",
      disabled = false,
      children = "Submit",
      loadingText = "Processing…",
      successText = "Done",
      className,
    },
    ref
  ) => {
    const reduced = !!useReducedMotion();
    const isIdle = state === "idle";

    // Only the idle state is interactive; loading and success ignore clicks
    const isDisabled = disabled || !isIdle;

    // Each state's content slides and blurs in and out
    const content = {
      initial: reduced ? { opacity: 0 } : { opacity: 0, y: 12, filter: "blur(4px)" },
      animate: reduced ? { opacity: 1 } : { opacity: 1, y: 0, filter: "blur(0px)" },
      exit: reduced ? { opacity: 0 } : { opacity: 0, y: -12, filter: "blur(4px)" },
      transition: { duration: reduced ? 0.1 : 0.25, ease: "easeOut" as const },
    };

    return (
      <motion.button
        ref={ref}
        type={type}
        onClick={onClick}
        disabled={isDisabled}
        aria-busy={state === "loading"}
        aria-live="polite"
        // `layout` animates the width change; the radius is set inline so it never stretches
        layout={!reduced}
        style={{ borderRadius: 12 }}
        transition={{ layout: { type: "spring", stiffness: 500, damping: 36 } }}
        whileTap={isIdle && !disabled && !reduced ? { scale: 0.96 } : undefined}
        className={cn(
          "relative inline-flex h-11 min-w-32 items-center justify-center overflow-hidden px-6 text-sm font-medium",
          "transition-[background-color,color,box-shadow] duration-300",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          state === "success"
            ? "bg-emerald-600 text-white shadow-lg shadow-emerald-600/25 dark:bg-emerald-500 dark:shadow-emerald-500/20"
            : "bg-primary text-primary-foreground shadow-sm hover:bg-primary/90",
          // Dim only when the parent disables it, not during loading or success
          disabled && isIdle && "cursor-not-allowed opacity-50",
          state === "loading" && "cursor-progress",
          className
        )}
      >
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span key={state} {...content} className="flex items-center gap-2 whitespace-nowrap">
            {state === "loading" && <Spinner />}
            {state === "success" && <AnimatedCheck reduced={reduced} />}
            {state === "idle" ? children : state === "loading" ? loadingText : successText}
          </motion.span>
        </AnimatePresence>
      </motion.button>
    );
  }
);

MultiStateSubmitButton.displayName = "MultiStateSubmitButton";

